95: function pointToMap(clientX, clientY) {
96:   const r = canvas.getBoundingClientRect();
97:   const px = clientX - r.left;
98:   const py = clientY - r.top;
99:   return {
100:     px, py,
101:     nx: px / Math.max(1, r.width),
102:     ny: py / Math.max(1, r.height),
103:     inside: px >= 0 && py >= 0 && px <= r.width && py <= r.height,
104:   };
105: }
