107: let toastTimer = 0;
108: function toast(message, type = '') {
109:   const wrap = $('#toasts');
110:   const key = message + type;
111:   const now = performance.now();
112:   const existing = [...wrap.children].find(el => el.dataset.key === key);
113:   if (existing && now - toastTimer < 500) return;
114:   toastTimer = now;
115:   const el = document.createElement('div');
116:   el.className = `toast ${type}`;
117:   el.dataset.key = key;
118:   el.textContent = message;
119:   wrap.appendChild(el);
120:   while (wrap.children.length > 3) wrap.removeChild(wrap.firstChild);
121:   setTimeout(() => {
122:     el.classList.add('out');
123:     setTimeout(() => el.remove(), 320);
124:   }, 2600);
125: }
