167: 
168: function onCardDown(e, type, card) {
169:   if (e.button !== undefined && e.button !== 0) return;
170:   if (!game.started) return;
171:   if (game.phase === 'victory' || game.phase === 'defeat') return;
172:   e.preventDefault();
173:   audio.ensure();
174:   const def = TOWERS[type];
175:   if (game.credits < def.cost) {
176:     audio.error();
177:     toast(`Need ${def.cost - game.credits} more credits for ${def.short}`, 'bad');
178:     return;
179:   }
180:   drag = {
181:     type,
182:     card,
183:     startX: e.clientX,
184:     startY: e.clientY,
185:     moved: false,
186:     pointerId: e.pointerId,
187:     captured: false,
188:   };
189:   try {
190:     card.setPointerCapture(e.pointerId);
191:     drag.captured = true;
192:   } catch {}
193: }
