195: window.addEventListener('pointermove', (e) => {
196:   if (!drag) return;
197:   if (!drag.moved) {
198:     const dx = e.clientX - drag.startX;
199:     const dy = e.clientY - drag.startY;
200:     if (Math.hypot(dx, dy) < 7) return;
201:     drag.moved = true;
202:     audio.ensure();
203:     // close inspector + arm the tower
204:     closeInspector(true);
205:     if (selectedType) cancelPlacement(true);
206:     selectedType = drag.type;
207:     game.setPending(drag.type);
208:     setArmed(drag.type);
209:     drag.card.classList.add('dragging');
210:     dragGhost.innerHTML = `
211:       <span class="tower-icon">${TOWERS[drag.type].icon}</span>
212:       <span class="ghost-name">${TOWERS[drag.type].short}</span>
213:       <span class="ghost-cost">${COIN}${TOWERS[drag.type].cost}</span>`;
214:     dragGhost.classList.remove('hidden');
215:     dragGhost.classList.remove('bad');
216:     ghostVisible = true;
217:     audio.ui();
218:   }
219:   if (!drag.moved) return;
220:   dragGhost.style.left = `${e.clientX}px`;
221:   dragGhost.style.top = `${e.clientY}px`;
222:   const pos = pointToMap(e.clientX, e.clientY);
223:   if (pos.inside) {
224:     game.setPreview(pos.nx, pos.ny);
225:     const valid = game.preview?.valid ?? false;
226:     dragGhost.classList.toggle('bad', !valid);
227:     placeHint.classList.add('hidden');
228:   } else {
229:     game.setPreview(null);
230:     dragGhost.classList.remove('bad');
231:   }
232: });
233: 
234: window.addEventListener('pointerup', (e) => {
235:   if (!drag) return;
236:   const d = drag;
237:   drag = null;
238:   try { if (d.captured && d.card.hasPointerCapture(d.pointerId)) d.card.releasePointerCapture(d.pointerId); } catch {}
239:   d.card.classList.remove('dragging');
240:   dragGhost.classList.add('hidden');
241:   ghostVisible = false;
242: 
243:   if (!d.moved) {
244:     // tap on the card → arm placement for the next map tap
245:     if (selectedType === d.type) {
246:       cancelPlacement();
247:     } else {
248:       closeInspector(true);
249:       game.setPending(d.type);
250:       selectedType = d.type;
251:       setArmed(d.type);
252:       audio.ui();
253:       toast(`Tap the sand to deploy ${TOWERS[d.type].short}`);
254:     }
255:     return;
256:   }
257: 
258:   const pos = pointToMap(e.clientX, e.clientY);
259:   let placed = false;
260:   let reason = '';
261:   if (pos.inside) {
262:     const res = game.placeTower(d.type, pos.nx, pos.ny);
263:     placed = res.ok;
264:     reason = res.reason;
265:   }
266:   game.setPending(null);
267:   game.setPreview(null);
268:   selectedType = null;
269:   setArmed(null);
270:   if (placed) {
271:     toast(`${TOWERS[d.type].name} deployed`, 'good');
272:   } else if (pos.inside && reason) {
273:     audio.error();
274:     toast(reason, 'bad');
275:   }
276:   syncUI(true);
277: });
