364: function refreshInspector() {
365:   const t = game.selected;
366:   if (!t) { closeInspector(true); return; }
367:   const def = TOWERS[t.type];
368:   const lv = towerLevel(t.type, t.level);
369:   $('#inspectIcon').innerHTML = def.icon;
370:   $('#inspectName').textContent = def.name;
371:   $('#inspectLevel').textContent = `LEVEL ${t.level} / 4  ·  ${def.role}`;
372:   $('#inspectDesc').textContent = def.desc;
373:   $('#statDamage').textContent = lv.damage % 1 === 0 ? lv.damage : lv.damage.toFixed(1);
374:   $('#statRange').textContent = Math.round(lv.range);
375:   $('#statRate').textContent = `${(1 / lv.cooldown).toFixed(1)}/s`;
376:   const mode = TARGET_MODES.find(m => m.id === t.mode) || TARGET_MODES[0];
377:   $('#targetMode').textContent = mode.label;
378:   $('#targetBtn').title = `Priority: ${mode.desc}. Tap to change.`;
379:   const up = $('#upgradeBtn');
380:   if (lv.nextLevel) {
381:     up.classList.remove('maxed');
382:     up.classList.toggle('disabled', game.credits < lv.upgrade);
383:     up.querySelector('.up-label').textContent = `UPGRADE TO LEVEL ${lv.nextLevel}`;
384:     up.querySelector('.up-cost').innerHTML = `${COIN}<b id="upgradeCost">${fmt(lv.upgrade)}</b>`;
385:     $('#upgradeDelta').textContent = lv.note;
386:     up.title = `Upgrade for ${lv.upgrade} credits: ${lv.note}`;
387:   } else {
388:     up.classList.add('maxed');
389:     up.classList.remove('disabled');
390:     up.querySelector('.up-label').textContent = 'ELITE TIER REACHED';
391:     up.querySelector('.up-cost').innerHTML = '<b>MAX</b>';
392:     $('#upgradeDelta').textContent = 'This tower is fully upgraded';
393:     up.title = 'Fully upgraded';
394:   }
395:   $('#sellValue').textContent = fmt(sellValue(t));
396: }
