439: let lastHud = { credits: -1, lives: -1, wave: -1, started: false };
440: let lastIntelKey = '';
441: 
442: function syncIntel(h) {
443:   const key = `${game.started}:${h.wave}:${h.phase}`;
444:   if (key === lastIntelKey) return;
445:   lastIntelKey = key;
446:   const body = $('#intelBody');
447:   const threat = $('#intelThreat');
448:   const title = $('#intelTitle');
449:   if (!body) return;
450:   if (!game.started) {
451:     body.innerHTML = '<span class="intel-tip">Deploy the outpost to see droid movements.</span>';
452:     threat.textContent = 'STANDBY';
453:     threat.className = 'threat';
454:     return;
455:   }
456:   if (h.phase === 'victory' || h.phase === 'defeat') {
457:     body.innerHTML = '<span class="intel-tip">Mission concluded. Redeploy for another run.</span>';
458:     threat.textContent = h.phase === 'victory' ? 'SECURED' : 'OFFLINE';
459:     threat.className = 'threat';
460:     return;
461:   }
462:   title.textContent = h.phase === 'wave' ? 'WAVE INTEL' : 'NEXT WAVE INTEL';
463:   const specs = makeWave(h.wave);
464:   const counts = {};
465:   for (const s of specs) counts[s.type] = (counts[s.type] || 0) + 1;
466:   const order = ['droid', 'scout', 'tank', 'boss'];
467:   const labels = { droid: 'B1', scout: 'STAP', tank: 'B2', boss: 'CMD' };
468:   body.innerHTML = order
469:     .filter(t => counts[t])
470:     .map(t => `<span class="intel-chip"><i class="enemy-dot ${t === 'boss' ? 'boss' : ''}" style="--dotc:${ENEMY_TYPES[t].color}"></i><b>${counts[t]}</b>${labels[t]}</span>`)
471:     .join('');
472:   let level = 'LOW';
473:   if (h.wave > 18 || h.wave % 10 === 0) level = 'EXTREME';
474:   else if (h.wave > 11) level = 'HIGH';
475:   else if (h.wave > 4) level = 'MODERATE';
476:   threat.textContent = `${level} THREAT`;
477:   threat.className = `threat ${level === 'MODERATE' ? 'moderate' : level === 'HIGH' ? 'high' : level === 'EXTREME' ? 'extreme' : ''}`;
478: }
