480: function syncUI(force = false) {
481:   if (!game) return;
482:   const h = game.hud();
483: 
484:   const creditsEl = $('#credits');
485:   const livesEl = $('#lives');
486:   if (force || h.credits !== lastHud.credits) {
487:     creditsEl.textContent = fmt(h.credits);
488:     lastHud.credits = h.credits;
489:   }
490:   if (force || h.lives !== lastHud.lives) {
491:     livesEl.textContent = h.lives;
492:     livesEl.parentElement.classList.toggle('low', h.lives <= 5);
493:     if (h.lives < lastHud.lives && game.started) {
494:       livesEl.parentElement.classList.remove('bump');
495:       void livesEl.parentElement.offsetWidth;
496:       livesEl.parentElement.classList.add('bump');
497:     }
498:     lastHud.lives = h.lives;
499:   }
500: 
501:   const waveEl = $('#waveTag');
502:   const cap = h.endless ? '&infin;' : TOTAL_WAVES;
503:   waveEl.innerHTML = `WAVE ${h.wave} <i>/ ${cap}</i>`;
504:   $('#waveSub').textContent = h.phase === 'wave' ? `${h.alive + h.queue} hostile${h.alive + h.queue === 1 ? '' : 's'}` : h.phase === 'build' ? (h.wave > 1 ? 'Build phase' : 'Prepare defenses') : h.phase === 'victory' ? 'Relay held' : 'Relay lost';
505:   $('#waveProgress').style.width = `${(h.phase === 'wave' ? h.progress : 0) * 100}%`;
506: 
507:   const statusEl = $('#waveStatus');
508:   const remaining = h.alive + h.queue;
509:   statusEl.classList.toggle('active', h.phase === 'wave');
510:   statusEl.classList.toggle('danger', h.phase === 'defeat' || (h.lives <= 5 && h.phase === 'wave'));
511:   if (!game.started) {
512:     statusEl.innerHTML = '<span class="status-dot"></span>Deploy to begin';
513:   } else if (h.phase === 'wave') {
514:     statusEl.innerHTML = `<span class="status-dot"></span>Wave ${h.wave} — ${remaining} hostile${remaining === 1 ? '' : 's'} left`;
515:   } else if (h.phase === 'victory') {
516:     statusEl.innerHTML = '<span class="status-dot"></span>Outpost secured';
517:   } else if (h.phase === 'defeat') {
518:     statusEl.innerHTML = '<span class="status-dot"></span>Relay destroyed';
519:   } else if (h.lives <= 5) {
520:     statusEl.innerHTML = `<span class="status-dot"></span>Relay critical — ${h.lives} integrity`;
521:   } else {
522:     statusEl.innerHTML = `<span class="status-dot"></span>Wave ${h.wave} ready — ${game.towers.length ? 'send when ready' : 'place your towers'}`;
523:   }
524: 
525:   const send = $('#nextWaveBtn');
526:   const canSend = game.started && h.phase === 'build';
527:   send.disabled = !canSend;
528:   send.classList.toggle('in-wave', game.started && (h.phase === 'wave' || h.phase === 'victory' || h.phase === 'defeat'));
529:   if (!game.started) {
530:     $('#sendLabel').textContent = 'Deploy Outpost';
531:     $('#sendSub').textContent = 'Place towers, hold the relay';
532:   } else if (h.phase === 'build') {
533:     $('#sendLabel').textContent = `Send Wave ${h.wave}`;
534:     $('#sendSub').textContent = `Clear bonus +${waveReward(h.wave)} credits`;
535:   } else if (h.phase === 'wave') {
536:     $('#sendLabel').textContent = `Wave ${h.wave} in progress`;
537:     $('#sendSub').textContent = `${remaining} hostile${remaining === 1 ? '' : 's'} remaining`;
538:   } else if (h.phase === 'victory') {
539:     $('#sendLabel').textContent = 'Outpost secured';
540:     $('#sendSub').textContent = 'The relay is safe';
541:   } else {
542:     $('#sendLabel').textContent = 'Relay destroyed';
543:     $('#sendSub').textContent = 'Redeploy to try again';
544:   }
545: 
546:   // affordability
547:   for (const el of towerList.children) {
