69:     this.h = 1;
70:     this.S = 1;
71:     this.pathPts = [];
72:     this.pathLen = 1;
73:     this.bg = null;
74:     this.time = 0;
75:     this.realTime = 0;
76:     this.started = false;
77:     this.paused = false;
78:     this.speed = 1;
79:     this.preview = null;
80:     this.pendingType = null;
