96:     this.lives = START_LIVES;
97:     this.waveNumber = 1;
98:     this.waveActive = false;
99:     this.spawnQueue = null;
100:     this.spawnTimer = 0;
101:     this.waveTotal = 0;
102:     this.waveSpawned = 0;
103:     this.enemies = [];
104:     this.towers = [];
105:     this.projectiles = [];
106:     this.particles = [];
107:     this.effects = [];
108:     this.kills = 0;
109:     this.creditsEarned = 0;
110:     this.selected = null;
111:     this.pendingType = null;
112:     this.preview = null;
113:     this.phase = 'build';
114:     this.endless = false;
115:     this.bossRef = null;
116:     this.shake = 0;
117:     this.baseFlash = 0;
118:     this.dustTimer = 0;
119:     this.spawnPoint = [0, 0];
120:   }
121: 
122:   resize(w, h, dpr) {
123:     this.dpr = dpr;
124:     this.w = Math.max(1, w);
125:     this.h = Math.max(1, h);
126:     this.canvas.width = Math.floor(this.w * dpr);
127:     this.canvas.height = Math.floor(this.h * dpr);
128:     this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
129:     this.S = clamp(Math.min(this.w / 960, this.h / 640), 0.58, 1.55);
130:     this.pathPts = samplePath(PATH_POINTS, this.w, this.h);
131:     let len = 0;
132:     for (let i = 1; i < this.pathPts.length; i++) {
133:       len += Math.hypot(this.pathPts[i][0] - this.pathPts[i - 1][0], this.pathPts[i][1] - this.pathPts[i - 1][1]);
134:     }
135:     this.pathLen = Math.max(1, len);
136:     this.spawnPoint = this.pathPts[0] || [0, 0];
137:     this.bg = buildBackground(this.w, this.h, this.pathPts, this.S, Math.min(dpr, 2));
138:     for (const t of this.towers) {
139:       t.x = t.nx * this.w;
140:       t.y = t.ny * this.h;
141:     }
142:     for (const e of this.enemies) {
143:       this.positionEnemy(e);
144:     }
145:   }
146: 
147:   begin() {
148:     if (this.started) return;
149:     this.started = true;
150:     this.phase = 'build';
151:     this.credits = START_CREDITS;
152:     this.lives = START_LIVES;
153:   }
154: 
155:   setSpeed(s) {
156:     this.speed = s;
157:   }
158: 
159:   /* ---------------- path & placement ---------------- */
160: 
161:   pathWidth() {
162:     return clamp(34 * this.S, 28, 54);
163:   }
164: 
165:   distanceToPath(x, y) {
166:     return pointDistanceToPath(x, y, this.pathPts);
167:   }
168: 
169:   canPlace(type, nx, ny) {
170:     const def = TOWERS[type];
171:     if (!def) return { ok: false, reason: 'Unknown tower' };
172:     if (!this.started) return { ok: false, reason: 'Deploy the outpost first' };
173:     if (this.phase === 'defeat' || this.phase === 'victory') return { ok: false, reason: 'Run over' };
174:     if (this.credits < def.cost) return { ok: false, reason: `Need ${def.cost - this.credits} more credits` };
175:     const x = nx * this.w;
176:     const y = ny * this.h;
177:     const S = this.S;
178:     const marginX = 20 * S;
179:     const top = Math.max(48, 40 * S);
180:     const bottom = this.h - 14 * S;
181:     if (x < marginX || x > this.w - marginX || y < top || y > bottom) {
182:       return { ok: false, reason: 'Too close to the edge' };
183:     }
184:     if (this.distanceToPath(x, y) < this.pathWidth() / 2 + 26 * S) {
185:       return { ok: false, reason: "Can't build on the droid route" };
186:     }
187:     const m = Math.min(this.w, this.h);
188:     for (const d of DECOR) {
189:       const dx = d.x * this.w;
190:       const dy = d.y * this.h;
191:       const dr = d.r * m;
192:       if (Math.hypot(x - dx, y - dy) < dr + 24 * S) {
193:         return { ok: false, reason: 'Obstructed — pick clear sand' };
194:       }
195:     }
196:     const baseX = BASE.x * this.w;
197:     const baseY = BASE.y * this.h;
198:     if (Math.hypot(x - baseX, y - baseY) < clamp(m * 0.085, 44, 96) + 16 * S) {
199:       return { ok: false, reason: 'Too close to the relay' };
200:     }
201:     for (const t of this.towers) {
202:       if (Math.hypot(x - t.x, y - t.y) < 41 * S) {
203:         return { ok: false, reason: 'Another tower is in the way' };
204:       }
205:     }
206:     return { ok: true, reason: '' };
207:   }
208: 
209:   placeTower(type, nx, ny) {
210:     const check = this.canPlace(type, nx, ny);
211:     if (!check.ok) return check;
212:     const def = TOWERS[type];
213:     const lv = towerLevel(type, 1);
214:     const tower = {
215:       id: this.uid++,
216:       type,
217:       nx, ny,
218:       x: nx * this.w,
219:       y: ny * this.h,
220:       level: 1,
221:       range: lv.range,
222:       damage: lv.damage,
223:       cooldown: lv.cooldown,
224:       splash: lv.splash,
225:       slow: lv.slow,
226:       slowDuration: lv.slowDuration,
227:       chain: lv.chain,
228:       cooldownLeft: 0.15,
229:       angle: -Math.PI / 2,
230:       targetAngle: -Math.PI / 2,
231:       recoil: 0,
232:       mode: 'first',
233:       spent: def.cost,
234:       phase: Math.random() * TAU,
235:       flash: 0,
236:     };
237:     this.credits -= def.cost;
238:     this.towers.push(tower);
239:     this.effects.push({ kind: 'ring', x: tower.x, y: tower.y, r: 6 * this.S, maxR: 38 * this.S, color: '#ffe6a6', width: 2.4 * this.S, life: 0.4, max: 0.4, alpha: 0.9 });
240:     this.spark(tower.x, tower.y, 10, '#ffd98a', 2.4);
241:     this.audio.place();
242:     return { ok: true, tower, reason: '' };
243:   }
244: 
245:   selectTower(tower) {
246:     if (!tower) { this.selected = null; return; }
247:     this.selected = tower;
248:     this.pendingType = null;
249:     this.preview = null;
250:   }
251: 
252:   towerAt(px, py) {
253:     for (let i = this.towers.length - 1; i >= 0; i--) {
254:       const t = this.towers[i];
255:       if (Math.hypot(px - t.x, py - t.y) < 34 * this.S) return t;
256:     }
257:     return null;
258:   }
259: 
260:   setPending(type) {
261:     this.pendingType = type;
262:     this.preview = null;
263:     if (type) this.selected = null;
264:   }
265: 
266:   setPreview(nx, ny) {
267:     if (!this.pendingType) { this.preview = null; return; }
268:     if (nx == null || ny == null) { this.preview = null; return; }
269:     const check = this.canPlace(this.pendingType, nx, ny);
270:     this.preview = { type: this.pendingType, nx, ny, valid: check.ok };
271:   }
272: 
273:   tryPlaceDefault(type, nx, ny) {
274:     const result = this.placeTower(type, nx, ny);
275:     if (result.ok) {
276:       this.pendingType = null;
277:       this.preview = null;
278:     }
279:     return result;
280:   }
281: 
282:   upgradeSelected() {
283:     const t = this.selected;
284:     if (!t || t.level >= 4) return { ok: false, reason: 'Already max level' };
285:     const lv = towerLevel(t.type, t.level);
286:     if (this.credits < lv.upgrade) return { ok: false, reason: `Need ${lv.upgrade - this.credits} more credits` };
287:     this.credits -= lv.upgrade;
288:     t.spent += lv.upgrade;
289:     t.level++;
290:     const next = towerLevel(t.type, t.level);
291:     t.range = next.range;
292:     t.damage = next.damage;
293:     t.cooldown = next.cooldown;
294:     t.splash = next.splash;
295:     t.slow = next.slow;
296:     t.slowDuration = next.slowDuration;
297:     t.chain = next.chain;
298:     t.flash = 1;
299:     this.effects.push({ kind: 'ring', x: t.x, y: t.y, r: 8 * this.S, maxR: 46 * this.S, color: '#8ff0ff', width: 2.5 * this.S, life: 0.5, max: 0.5 });
300:     this.effects.push({ kind: 'flash', x: t.x, y: t.y, r: 46 * this.S, color: 'rgba(130, 225, 255, 0.35)', life: 0.35, max: 0.35 });
301:     this.spark(t.x, t.y, 16, '#b9f4ff', 3);
302:     this.audio.upgrade();
303:     return { ok: true };
304:   }
305: 
306:   sellSelected() {
307:     const t = this.selected;
308:     if (!t) return { ok: false };
309:     const value = sellValue(t);
310:     this.credits += value;
311:     this.towers = this.towers.filter(x => x !== t);
312:     this.selected = null;
313:     this.effects.push({ kind: 'ring', x: t.x, y: t.y, r: 12 * this.S, maxR: 40 * this.S, color: '#ffce7a', width: 2, life: 0.45, max: 0.45 });
314:     this.effects.push({ kind: 'text', x: t.x, y: t.y - 10, text: `+${value}`, color: '#ffe2a0', size: 13 * this.S, life: 0.8, max: 0.8 });
315:     this.spark(t.x, t.y, 8, '#ffce7a', 2);
316:     this.audio.sell();
317:     return { ok: true, value };
318:   }
319: 
320:   cycleTarget() {
321:     if (!this.selected) return;
322:     const i = TARGET_MODES.findIndex(m => m.id === this.selected.mode);
323:     this.selected.mode = TARGET_MODES[(i + 1) % TARGET_MODES.length].id;
324:     this.audio.ui();
325:   }
326: 
327:   /* ---------------- waves ---------------- */
328: 
329:   startWave() {
330:     if (!this.started || this.paused || this.waveActive) return false;
331:     if (this.phase !== 'build') return false;
332:     const specs = makeWave(this.waveNumber);
333:     let last = 0;
334:     this.spawnQueue = specs.map(s => {
335:       const gap = Math.max(0.08, s.delay - last);
336:       last = s.delay;
337:       return { ...s, gap };
338:     });
339:     this.spawnTimer = this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
340:     this.waveTotal = this.spawnQueue.length;
341:     this.waveSpawned = 0;
342:     this.waveActive = true;
343:     this.phase = 'wave';
344:     this.bossRef = null;
345:     this.audio.waveStart();
346:     this.effects.push({ kind: 'ring', x: this.w * 0.04, y: this.h * 0.64, r: 8 * this.S, maxR: 64 * this.S, color: '#ff8a63', width: 2, life: 0.7, max: 0.7 });
347:     this.callbacks.onWaveStart?.(this.waveNumber);
348:     if (this.waveNumber === TOTAL_WAVES && !this.endless) {
349:       this.callbacks.toast?.('Final wave — hold the relay!', 'bad');
350:     } else if (this.waveNumber % 10 === 0) {
351:       this.callbacks.toast?.('Command droid inbound', 'bad');
352:     }
353:     return true;
354:   }
355: 
356:   spawnEnemy(spec) {
357:     const def = ENEMY_TYPES[spec.type];
358:     const e = {
359:       id: this.uid++,
360:       type: spec.type,
361:       hp: spec.hp,
362:       maxHp: spec.hp,
363:       speed: spec.speed * (0.95 + Math.random() * 0.1),
364:       t: 0,
365:       x: this.pathPts[0][0],
366:       y: this.pathPts[0][1],
367:       angle: 0,
368:       radius: def.radius,
369:       slowT: 0,
370:       slowFactor: 0,
371:       hitFlash: 0,
372:       phase: Math.random() * TAU,
373:       dead: false,
374:       reward: enemyReward(spec.type, this.waveNumber),
375:       leak: def.leak,
376:       isBoss: spec.type === 'boss',
377:     };
378:     this.positionEnemy(e);
379:     this.enemies.push(e);
380:     this.waveSpawned++;
381:     if (e.isBoss) {
382:       this.bossRef = e;
383:       this.audio.bossWarn();
384:       this.shake = Math.max(this.shake, 5);
385:       this.callbacks.onBoss?.();
386:       this.callbacks.toast?.('Droid commander on the field', 'bad');
387:       this.effects.push({ kind: 'ring', x: e.x, y: e.y, r: 10 * this.S, maxR: 90 * this.S, color: '#ff8a63', width: 3, life: 0.7, max: 0.7 });
388:     }
389:   }
390: 
391:   positionEnemy(e) {
392:     const n = this.pathPts.length;
393:     if (!n) return;
394:     const f = clamp(e.t, 0, 1) * (n - 1);
395:     const i0 = Math.min(n - 1, Math.floor(f));
396:     const i1 = Math.min(n - 1, i0 + 1);
397:     const frac = f - i0;
398:     const a = this.pathPts[i0];
399:     const b = this.pathPts[i1];
400:     e.x = a[0] + (b[0] - a[0]) * frac;
401:     e.y = a[1] + (b[1] - a[1]) * frac;
402:     e.angle = Math.atan2(b[1] - a[1], b[0] - a[0]);
403:   }
404: 
405:   completeWave() {
406:     if (!this.waveActive) return;
407:     this.waveActive = false;
408:     this.spawnQueue = null;
409:     const bonus = waveReward(this.waveNumber);
410:     this.credits += bonus;
411:     this.creditsEarned += bonus;
412:     this.audio.waveClear();
413:     this.callbacks.toast?.(`Wave ${this.waveNumber} cleared  +${bonus} credits`, 'good');
414:     this.effects.push({ kind: 'ring', x: BASE.x * this.w, y: BASE.y * this.h, r: 12 * this.S, maxR: 90 * this.S, color: '#8ff0b0', width: 2, life: 0.8, max: 0.8 });
415: 
416:     if (!this.endless && this.waveNumber >= TOTAL_WAVES) {
417:       this.win();
418:       return;
419:     }
420:     this.waveNumber++;
421:     this.phase = 'build';
422:     this.selected = null;
423:     this.callbacks.onWaveClear?.(this.waveNumber, bonus);
424:   }
425: 
426:   win() {
427:     if (this.phase === 'victory') return;
428:     this.phase = 'victory';
429:     this.waveActive = false;
430:     this.audio.victory();
431:     this.callbacks.onEnd?.(true);
432:   }
433: 
434:   defeat() {
435:     if (this.phase === 'defeat') return;
436:     this.phase = 'defeat';
437:     this.waveActive = false;
438:     this.audio.defeat();
439:     this.shake = 16;
440:     this.callbacks.onEnd?.(false);
441:   }
442: 
443:   continueEndless() {
444:     this.endless = true;
445:     this.phase = 'build';
446:     if (this.waveNumber <= TOTAL_WAVES) this.waveNumber = TOTAL_WAVES + 1;
447:     this.lives = Math.max(this.lives, 10);
448:     this.selected = null;
449:     this.paused = false;
450:     this.callbacks.toast?.('Endless mode — the droid army is endless too', 'bad');
451:   }
452: 
453:   /* ---------------- update ---------------- */
454: 
455:   update(rawDt) {
456:     const rdt = Math.min(rawDt, 0.15);
457:     this.realTime += rdt;
458:     if (!this.started || this.paused || this.phase === 'victory' || this.phase === 'defeat') {
459:       this.updateFx(rdt);
460:       return;
461:     }
462:     // Fixed substeps keep the simulation real-time even at low frame rates.
463:     const total = rdt * this.speed;
464:     const steps = Math.max(1, Math.ceil(total / 0.033));
465:     const dt = total / steps;
466:     for (let i = 0; i < steps; i++) {
467:       this.stepSim(dt);
468:       if (this.phase === 'victory' || this.phase === 'defeat') break;
469:     }
470:   }
471: 
472:   stepSim(dt) {
473:     this.time += dt;
474: 
475:     // ambient dust
476:     this.dustTimer -= dt;
477:     if (this.dustTimer <= 0) {
478:       this.dustTimer = 0.35 + Math.random() * 0.5;
479:       if (this.particles.length < 260) {
480:         this.particles.push({
481:           x: Math.random() * this.w,
482:           y: this.h * (0.25 + Math.random() * 0.7),
483:           vx: (10 + Math.random() * 26) * this.S,
484:           vy: (2 + Math.random() * 8) * this.S,
485:           life: 3.5 + Math.random() * 4,
486:           max: 7,
487:           size: (0.7 + Math.random() * 1.2) * this.S,
488:           color: 'rgba(255, 233, 185, 0.35)',
489:           glow: false,
490:           gravity: 0,
491:           drag: 0.99,
492:         });
493:       }
494:     }
495: 
496:     if (this.waveActive && this.spawnQueue) {
497:       this.spawnTimer -= dt;
498:       let guard = 0;
499:       while (this.spawnTimer <= 0 && this.spawnQueue.length && guard++ < 20) {
500:         const spec = this.spawnQueue.shift();
501:         this.spawnEnemy(spec);
502:         this.spawnTimer += this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
503:       }
504:     }
505: 
506:     this.updateEnemies(dt);
507:     this.updateTowers(dt);
508:     this.updateProjectiles(dt);
509:     this.updateFx(dt);
510:     this.cleanup();
511: 
512:     if (this.waveActive && (!this.spawnQueue || this.spawnQueue.length === 0) && this.enemies.length === 0) {
513:       this.completeWave();
514:     }
515:     if (this.baseFlash > 0) this.baseFlash = Math.max(0, this.baseFlash - dt * 2);
516:     if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 34);
517:   }
518: 
519:   updateFx(dt) {
520:     for (const e of this.effects) e.life -= dt;
521:     for (const p of this.particles) {
522:       p.life -= dt;
523:       p.x += p.vx * dt;
524:       p.y += p.vy * dt;
525:       if (p.gravity) p.vy += p.gravity * dt;
526:       if (p.drag) { p.vx *= p.drag; p.vy *= p.drag; }
527:     }
528:     this.effects = this.effects.filter(e => e.life > 0);
529:     this.particles = this.particles.filter(p => p.life > 0 && p.x > -80 && p.x < this.w + 80 && p.y > -80 && p.y < this.h + 80);
530:   }
531: 
532:   updateEnemies(dt) {
533:     for (const e of this.enemies) {
534:       if (e.dead) continue;
535:       if (e.hitFlash > 0) e.hitFlash = Math.max(0, e.hitFlash - dt);
536:       if (e.slowT > 0) {
537:         e.slowT -= dt;
538:         if (e.slowT <= 0) { e.slowT = 0; e.slowFactor = 0; }
539:       }
540:       const slowMul = e.slowT > 0 ? 1 - e.slowFactor : 1;
541:       const pxPerSec = e.speed * this.S * slowMul;
542:       e.t += (pxPerSec * dt) / this.pathLen;
543:       if (e.t >= 1) {
544:         e.dead = true;
545:         this.leakEnemy(e);
546:       } else {
547:         this.positionEnemy(e);
548:       }
549:     }
550:   }
551: 
552:   leakEnemy(e) {
553:     this.lives -= e.leak;
554:     this.baseFlash = 1;
555:     this.shake = Math.max(this.shake, 8);
556:     this.audio.leak();
557:     this.effects.push({ kind: 'ring', x: BASE.x * this.w, y: BASE.y * this.h, r: 20 * this.S, maxR: 105 * this.S, color: '#ff6e58', width: 3, life: 0.7, max: 0.7 });
558:     this.effects.push({ kind: 'flash', x: BASE.x * this.w, y: BASE.y * this.h, r: 100 * this.S, color: 'rgba(255, 90, 70, 0.5)', life: 0.5, max: 0.5 });
559:     this.callbacks.toast?.(`Relay hit!  −${e.leak} integrity`, 'bad');
560:     this.callbacks.onLeak?.(e.leak);
561:     if (this.bossRef === e) this.bossRef = null;
562:     if (this.lives <= 0) {
563:       this.lives = 0;
564:       this.defeat();
565:     }
566:     if (this.phase === 'defeat') {
567:       // let the current frame finish; game over overlay takes over
568:     }
569:   }
570: 
571:   updateTowers(dt) {
572:     for (const t of this.towers) {
573:       if (t.flash > 0) t.flash = Math.max(0, t.flash - dt * 3);
574:       t.cooldownLeft -= dt;
575:       t.recoil = Math.max(0, t.recoil - dt * 7);
576:       const target = this.pickTarget(t);
577:       if (target) {
578:         const desired = Math.atan2(target.y - t.y, target.x - t.x);
579:         t.targetAngle = desired;
580:         t.angle = angleLerp(t.angle, desired, dt * 16);
581:         if (t.cooldownLeft <= 0) {
582:           this.fire(t, target);
583:           t.cooldownLeft = t.cooldown;
584:         }
585:       } else {
586:         t.targetAngle = t.angle;
587:         t.angle += dt * 0.18;
588:       }
589:     }
590:   }
591: 
592:   pickTarget(t) {
593:     const R2 = (t.range * this.S) ** 2;
