.art-rebel {
  isolation: isolate;
  background:
    radial-gradient(ellipse at 50% 110%, rgba(39, 101, 135, 0.48), transparent 48%),
    radial-gradient(ellipse at 75% 22%, rgba(67, 133, 174, 0.2), transparent 34%),
    linear-gradient(145deg, #07101f 0%, #101b31 54%, #182b3c 100%);
}
.art-rebel::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: 0.72;
  background-image:
    radial-gradient(circle, #e8e8d5 0 1px, transparent 1.5px),
    radial-gradient(circle, #84a8c0 0 1px, transparent 1.6px);
  background-position: 11px 8px, 30px 19px;
  background-size: 47px 37px, 71px 53px;
}
.rebel-planet {
  position: absolute;
  left: 18%;
  bottom: -42%;
  width: 34%;
  aspect-ratio: 1;
  border: 1px solid rgba(164, 213, 230, 0.38);
  border-radius: 50%;
  background:
    radial-gradient(ellipse at 35% 25%, rgba(217, 238, 224, 0.72) 0 3%, transparent 4%),
    radial-gradient(ellipse at 64% 38%, rgba(167, 210, 218, 0.52) 0 5%, transparent 6%),
    radial-gradient(circle at 34% 26%, #6f9dae, #315c75 45%, #172c48 72%);
  box-shadow: 0 0 24px rgba(109, 184, 216, 0.28), inset -10px -8px 18px rgba(0, 0, 0, 0.58);
}
.rebel-planet::after {
  content: "";
  position: absolute;
  inset: 44% -12%;
  border: 1px solid rgba(184, 214, 218, 0.28);
  border-left-color: transparent;
  border-right-color: transparent;
  border-radius: 50%;
  transform: rotate(-17deg);
}
.rebel-ship {
  position: absolute;
  top: 39%;
  right: 21%;
  width: 25%;
  height: 7%;
  background: linear-gradient(180deg, #d9e3dc, #687e83 55%, #273643);
  clip-path: polygon(0 42%, 32% 30%, 43% 0, 57% 0, 68% 30%, 100% 42%, 74% 58%, 59% 100%, 41% 100%, 26% 58%);
  filter: drop-shadow(0 0 5px rgba(158, 218, 240, 0.6));
  transform: rotate(-12deg);
}
.rebel-ship::after {
  content: "";
  position: absolute;
  left: 46%;
  top: 28%;
  width: 8%;
  height: 48%;
  background: #ffce75;
  box-shadow: 0 0 7px #ffae5d;
}
.rebel-star {
  position: absolute;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: #fff3cc;
  box-shadow: 0 0 6px 1px rgba(255, 227, 172, 0.72);
}
