1: /* ============================================================
2:    Canvas art — procedural Tatooine outpost
3:    All game visuals are drawn with the 2D canvas (no assets).
4:    ============================================================ */
5: 
6: import { DECOR, ENEMY_TYPES, TOWERS, clamp } from './data.js';
7: 
8: const TAU = Math.PI * 2;
9: const TOWER_ART = 1.32;
10: const ENEMY_ART = 2.02;
11: 
12: export function mulberry32(a) {
13:   return function () {
14:     a |= 0;
15:     a = (a + 0x6d2b79f5) | 0;
16:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
17:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
18:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
19:   };
20: }
21: 
22: function roundRect(ctx, x, y, w, h, r) {
23:   const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
24:   ctx.beginPath();
25:   ctx.moveTo(x + rr, y);
26:   ctx.arcTo(x + w, y, x + w, y + h, rr);
27:   ctx.arcTo(x + w, y + h, x, y + h, rr);
28:   ctx.arcTo(x, y + h, x, y, rr);
29:   ctx.arcTo(x, y, x + w, y, rr);
30:   ctx.closePath();
31: }
32: 
33: function tracePoints(ctx, pts) {
34:   if (!pts.length) return;
35:   ctx.beginPath();
36:   ctx.moveTo(pts[0][0], pts[0][1]);
37:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
38: }
39: 
40: function offsetPath(pts, off) {
41:   const out = [];
42:   for (let i = 0; i < pts.length; i++) {
43:     const p = pts[i];
44:     const prev = pts[Math.max(0, i - 1)];
45:     const next = pts[Math.min(pts.length - 1, i + 1)];
46:     let dx = next[0] - prev[0];
47:     let dy = next[1] - prev[1];
48:     const l = Math.hypot(dx, dy) || 1;
49:     dx /= l; dy /= l;
50:     out.push([p[0] - dy * off, p[1] + dx * off]);
51:   }
52:   return out;
53: }
